sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?village ?country WHERE {
  VALUES ?village { dbr:Haji_Kusa dbr:Shayta }
  OPTIONAL { ?village dbp:country ?c1 . }
  OPTIONAL { ?village dbo:country ?c2 . }
  BIND (COALESCE(?c1, ?c2) AS ?country)
}
LIMIT 100

